GTXT.found={"resp": {"name": "Гиперответственность", "foundations": [{"id": "resp_control", "title": "Страх потери контроля", "questions": [{"id": "q1", "text": {"m": "Тебе сложно передать другому человеку важное дело, потому что ты уверен, что без твоего контроля все пойдет не так?", "f": "Тебе сложно передать другому человеку важное дело, потому что ты уверена, что без твоего контроля все пойдет не так?"}}, {"id": "q2", "text": {"m": "Когда что-то идет не по плану, ты сразу чувствуешь, что обязан вмешаться и все исправить?", "f": "Когда что-то идет не по плану, ты сразу чувствуешь, что обязана вмешаться и все исправить?"}}], "explanation": {"m": "Ты берешь на себя больше, чем необходимо, потому что ответственность стала способом удерживать ситуацию под контролем. Внутреннее правило звучит так: «Если я не прослежу за всем, случится что-то плохое». Контроль дает временное спокойствие, но постепенно лишает тебя возможности опираться на других.", "f": "Ты берешь на себя больше, чем необходимо, потому что ответственность стала способом удерживать ситуацию под контролем. Внутреннее правило звучит так: «Если я не прослежу за всем, случится что-то плохое». Контроль дает временное спокойствие, но постепенно лишает тебя возможности опираться на других."}, "practices": [{"days": "1-7", "name": "Не вмешиваться раньше времени", "text": {"m": "Выбери одно небольшое дело, которое обычно контролируешь сам, и передай его другому. Не проверяй процесс до согласованного срока. В дневнике отметь, чего ты опасался и что произошло на самом деле.", "f": "Выбери одно небольшое дело, которое обычно контролируешь сама, и передай его другому. Не проверяй процесс до согласованного срока. В дневнике отметь, чего ты опасалась и что произошло на самом деле."}}, {"days": "8-14", "name": "Допустить другой способ", "text": {"m": "Позволь другому человеку выполнить знакомое тебе дело своим способом. Не исправляй результат только потому, что сделал бы иначе. Отдели реальную ошибку от отличия в подходе.", "f": "Позволь другому человеку выполнить знакомое тебе дело своим способом. Не исправляй результат только потому, что сделала бы иначе. Отдели реальную ошибку от отличия в подходе."}}, {"days": "15-21", "name": "Выбирать степень участия", "text": {"m": "Перед тем как вмешаться, задай себе три вопроса: действительно ли это моя ответственность, нужна ли сейчас моя помощь, что произойдет, если я подожду? Вмешивайся осознанно, а не автоматически.", "f": "Перед тем как вмешаться, задай себе три вопроса: действительно ли это моя ответственность, нужна ли сейчас моя помощь, что произойдет, если я подожду? Вмешивайся осознанно, а не автоматически."}}]}, {"id": "resp_needed", "title": "Потребность быть нужным", "questions": [{"id": "q1", "text": {"m": "Тебе трудно отказать в помощи, потому что возникает ощущение, что без тебя человек не справится или перестанет в тебе нуждаться?", "f": "Тебе трудно отказать в помощи, потому что возникает ощущение, что без тебя человек не справится или перестанет в тебе нуждаться?"}}, {"id": "q2", "text": {"m": "Ты чувствуешь себя особенно ценным, когда кто-то зависит от тебя, благодарит тебя или обращается именно к тебе?", "f": "Ты чувствуешь себя особенно ценной, когда кто-то зависит от тебя, благодарит тебя или обращается именно к тебе?"}}], "explanation": {"m": "Ты связываешь собственную значимость с пользой, которую приносишь другим. Внутреннее правило: «Я нужен, пока помогаю». Забота становится способом заслуживать близость и признание. Но твоя ценность не должна зависеть от количества решенных чужих проблем.", "f": "Ты связываешь собственную значимость с пользой, которую приносишь другим. Внутреннее правило: «Я нужна, пока помогаю». Забота становится способом заслуживать близость и признание. Но твоя ценность не должна зависеть от количества решенных чужих проблем."}, "practices": [{"days": "1-7", "name": "Разделить помощь и обязанность", "text": {"m": "Перед каждой просьбой о помощи делай паузу. Запиши: я действительно хочу это сделать или боюсь разочаровать человека? Хотя бы один раз откажись от необязательной помощи без длинных оправданий.", "f": "Перед каждой просьбой о помощи делай паузу. Запиши: я действительно хочу это сделать или боюсь разочаровать человека? Хотя бы один раз откажись от необязательной помощи без длинных оправданий."}}, {"days": "8-14", "name": "Позволить себе принимать", "text": {"m": "Попроси о небольшой помощи и не компенсируй ее немедленно ответной услугой. Заметь, что ты чувствуешь, когда получаешь поддержку, а не только оказываешь ее.", "f": "Попроси о небольшой помощи и не компенсируй ее немедленно ответной услугой. Заметь, что ты чувствуешь, когда получаешь поддержку, а не только оказываешь ее."}}, {"days": "15-21", "name": "Быть ценным без пользы", "text": {"m": "Выдели время на занятие, которое не приносит пользы другим, не дает результата и не требует отчетности. Вечером запиши, что ты чувствовал, когда ничего никому не доказывал.", "f": "Выдели время на занятие, которое не приносит пользы другим, не дает результата и не требует отчетности. Вечером запиши, что ты чувствовала, когда ничего никому не доказывала."}}]}]}, "err": {"name": "Страх ошибки", "foundations": [{"id": "err_rejection", "title": "Страх отвержения и осуждения", "questions": [{"id": "q1", "text": {"m": "Ты откладываешь начало дела, потому что представляешь, как другие заметят твои ошибки и будут хуже к тебе относиться?", "f": "Ты откладываешь начало дела, потому что представляешь, как другие заметят твои ошибки и будут хуже к тебе относиться?"}}, {"id": "q2", "text": {"m": "Тебе проще отказаться от возможности, чем показать результат, который могут раскритиковать?", "f": "Тебе проще отказаться от возможности, чем показать результат, который могут раскритиковать?"}}], "explanation": {"m": "Для тебя ошибка означает не просто неудачный результат, а риск потерять уважение, принятие или близость. Внутреннее правило: «Если я ошибусь, меня отвергнут». Поэтому безопаснее не начинать, чем оказаться уязвимым перед чужой оценкой.", "f": "Для тебя ошибка означает не просто неудачный результат, а риск потерять уважение, принятие или близость. Внутреннее правило: «Если я ошибусь, меня отвергнут». Поэтому безопаснее не начинать, чем оказаться уязвимой перед чужой оценкой."}, "practices": [{"days": "1-7", "name": "Показать незавершенное", "text": {"m": "Покажи одному безопасному человеку небольшой результат, который еще не доведен до совершенства. Не проси немедленно оценивать тебя. Просто позволь результату существовать вне твоей головы.", "f": "Покажи одному безопасному человеку небольшой результат, который еще не доведен до совершенства. Не проси немедленно оценивать тебя. Просто позволь результату существовать вне твоей головы."}}, {"days": "8-14", "name": "Разделить ошибку и личность", "text": {"m": "После каждой ошибки запиши две отдельные фразы: «Что именно не получилось?» и «Что это говорит обо мне как о человеке?». Проверь, действительно ли вторая фраза следует из первой.", "f": "После каждой ошибки запиши две отдельные фразы: «Что именно не получилось?» и «Что это говорит обо мне как о человеке?». Проверь, действительно ли вторая фраза следует из первой."}}, {"days": "15-21", "name": "Действовать без гарантии одобрения", "text": {"m": "Выбери одно небольшое действие, которое давно откладывал из-за чужой оценки. Выполни его и не проверяй немедленно реакцию окружающих. Отметь, что ты способен выдержать отсутствие мгновенного одобрения.", "f": "Выбери одно небольшое действие, которое давно откладывала из-за чужой оценки. Выполни его и не проверяй немедленно реакцию окружающих. Отметь, что ты способна выдержать отсутствие мгновенного одобрения."}}]}, {"id": "err_perfection", "title": "Страх несоответствия собственному идеалу", "questions": [{"id": "q1", "text": {"m": "Ты продолжаешь готовиться, исправлять и улучшать работу, даже когда уже можешь показать достойный результат?", "f": "Ты продолжаешь готовиться, исправлять и улучшать работу, даже когда уже можешь показать достойный результат?"}}, {"id": "q2", "text": {"m": "Тебе трудно радоваться результату, потому что ты прежде всего замечаешь, что можно было сделать лучше?", "f": "Тебе трудно радоваться результату, потому что ты прежде всего замечаешь, что можно было сделать лучше?"}}], "explanation": {"m": "Ты боишься не столько чужой критики, сколько собственного разочарования. Внутреннее правило: «Я имею право гордиться собой, только если сделал идеально». Высокие стандарты могут помогать тебе расти, но становятся ограничением, когда не позволяют завершать и показывать работу.", "f": "Ты боишься не столько чужой критики, сколько собственного разочарования. Внутреннее правило: «Я имею право гордиться собой, только если сделала идеально». Высокие стандарты могут помогать тебе расти, но становятся ограничением, когда не позволяют завершать и показывать работу."}, "practices": [{"days": "1-7", "name": "Критерий достаточности", "text": {"m": "Перед началом задачи определи три признака, по которым поймешь, что она выполнена достаточно хорошо. Когда все три соблюдены, остановись.", "f": "Перед началом задачи определи три признака, по которым поймешь, что она выполнена достаточно хорошо. Когда все три соблюдены, остановись."}}, {"days": "8-14", "name": "Завершить без бесконечной доработки", "text": {"m": "Выбери небольшую задачу и установи срок завершения. Не возвращайся к ней ради незначительных улучшений после этого срока. Запиши, что изменилось в твоем ощущении результата.", "f": "Выбери небольшую задачу и установи срок завершения. Не возвращайся к ней ради незначительных улучшений после этого срока. Запиши, что изменилось в твоем ощущении результата."}}, {"days": "15-21", "name": "Признать сделанное", "text": {"m": "Каждый вечер запиши один результат, который ты создал, и одну его сильную сторону. Не добавляй после этого список недостатков.", "f": "Каждый вечер запиши один результат, который ты создала, и одну его сильную сторону. Не добавляй после этого список недостатков."}}]}]}, "appr": {"name": "Зависимость от одобрения", "foundations": [{"id": "appr_belonging", "title": "Страх потерять принадлежность", "questions": [{"id": "q1", "text": {"m": "Ты меняешь свое мнение или поведение, когда чувствуешь, что близкие могут не согласиться с тобой?", "f": "Ты меняешь свое мнение или поведение, когда чувствуешь, что близкие могут не согласиться с тобой?"}}, {"id": "q2", "text": {"m": "Тебе трудно выдержать ситуацию, когда важный для тебя человек недоволен тобой, даже если ты ничего плохого не сделал?", "f": "Тебе трудно выдержать ситуацию, когда важный для тебя человек недоволен тобой, даже если ты ничего плохого не сделала?"}}], "explanation": {"m": "Одобрение для тебя стало подтверждением безопасности отношений. Внутреннее правило: «Если мной недовольны, я могу потерять связь». Поэтому ты можешь отказываться от собственного мнения ради сохранения близости. Но несогласие не обязательно означает отвержение.", "f": "Одобрение для тебя стало подтверждением безопасности отношений. Внутреннее правило: «Если мной недовольны, я могу потерять связь». Поэтому ты можешь отказываться от собственного мнения ради сохранения близости. Но несогласие не обязательно означает отвержение."}, "practices": [{"days": "1-7", "name": "Сохранить собственное мнение", "text": {"m": "В одном безопасном разговоре спокойно вырази свое мнение, даже если оно отличается от мнения собеседника. Не превращай его в спор и не отказывайся от него ради немедленного согласия.", "f": "В одном безопасном разговоре спокойно вырази свое мнение, даже если оно отличается от мнения собеседника. Не превращай его в спор и не отказывайся от него ради немедленного согласия."}}, {"days": "8-14", "name": "Выдержать чужое недовольство", "text": {"m": "Если кто-то недоволен твоим решением, не спеши оправдываться или менять его. Дай себе время понять, есть ли реальная причина пересмотреть выбор или ты просто хочешь вернуть одобрение.", "f": "Если кто-то недоволен твоим решением, не спеши оправдываться или менять его. Дай себе время понять, есть ли реальная причина пересмотреть выбор или ты просто хочешь вернуть одобрение."}}, {"days": "15-21", "name": "Близость без подчинения", "text": {"m": "Выбери одно решение, которое важно тебе. Обсуди его с близким человеком, но оставь окончательный выбор за собой. Запиши, можно ли сохранять уважение и близость при разных взглядах.", "f": "Выбери одно решение, которое важно тебе. Обсуди его с близким человеком, но оставь окончательный выбор за собой. Запиши, можно ли сохранять уважение и близость при разных взглядах."}}]}, {"id": "appr_worth", "title": "Потребность подтверждать свою ценность", "questions": [{"id": "q1", "text": {"m": "Если тебя долго не хвалят и не замечают, начинаешь ли ты сомневаться в собственной значимости?", "f": "Если тебя долго не хвалят и не замечают, начинаешь ли ты сомневаться в собственной значимости?"}}, {"id": "q2", "text": {"m": "Ты часто рассказываешь о своих достижениях или ждешь реакции окружающих, чтобы почувствовать, что действительно чего-то стоишь?", "f": "Ты часто рассказываешь о своих достижениях или ждешь реакции окружающих, чтобы почувствовать, что действительно чего-то стоишь?"}}], "explanation": {"m": "Ты используешь внешнюю оценку как зеркало собственной значимости. Внутреннее правило: «Если меня не замечают, значит, я недостаточно хорош». Похвала дает краткое облегчение, но не создает устойчивой опоры. Тебе важно научиться замечать собственную ценность до того, как ее подтвердят другие.", "f": "Ты используешь внешнюю оценку как зеркало собственной значимости. Внутреннее правило: «Если меня не замечают, значит, я недостаточно хороша». Похвала дает краткое облегчение, но не создает устойчивой опоры. Тебе важно научиться замечать собственную ценность до того, как ее подтвердят другие."}, "practices": [{"days": "1-7", "name": "Замечать себя первой", "text": {"m": "Каждый вечер запиши три качества или решения, которые ты ценишь в себе независимо от того, заметил ли их кто-нибудь еще.", "f": "Каждый вечер запиши три качества или решения, которые ты ценишь в себе независимо от того, заметил ли их кто-нибудь еще."}}, {"days": "8-14", "name": "Не собирать подтверждения", "text": {"m": "Сделай что-то значимое для себя и не ищи немедленной реакции окружающих. Не публикуй результат ради похвалы. Сначала сам оцени, что для тебя в нем важно.", "f": "Сделай что-то значимое для себя и не ищи немедленной реакции окружающих. Не публикуй результат ради похвалы. Сначала сама оцени, что для тебя в нем важно."}}, {"days": "15-21", "name": "Принять признание", "text": {"m": "Когда получаешь комплимент, ответь простым «спасибо», не обесценивая себя и не доказывая, что результат случайный. Одновременно учись замечать свои достижения без чужих слов.", "f": "Когда получаешь комплимент, ответь простым «спасибо», не обесценивая себя и не доказывая, что результат случайный. Одновременно учись замечать свои достижения без чужих слов."}}]}]}, "deval": {"name": "Обесценивание хорошего", "foundations": [{"id": "deval_disappointment", "title": "Защита от разочарования", "questions": [{"id": "q1", "text": {"m": "Когда у тебя что-то получается, ты стараешься не радоваться заранее, потому что боишься, что все еще может испортиться?", "f": "Когда у тебя что-то получается, ты стараешься не радоваться заранее, потому что боишься, что все еще может испортиться?"}}, {"id": "q2", "text": {"m": "Тебе легче назвать свой успех случайностью, чем признать, что ты действительно хорошо справился?", "f": "Тебе легче назвать свой успех случайностью, чем признать, что ты действительно хорошо справилась?"}}], "explanation": {"m": "Ты уменьшаешь значение хорошего, чтобы не привязываться к нему и не испытывать боль, если оно исчезнет. Внутреннее правило: «Лучше не радоваться слишком сильно, тогда не будет так больно». Это защищает от ожиданий, но одновременно лишает тебя возможности проживать собственные достижения.", "f": "Ты уменьшаешь значение хорошего, чтобы не привязываться к нему и не испытывать боль, если оно исчезнет. Внутреннее правило: «Лучше не радоваться слишком сильно, тогда не будет так больно». Это защищает от ожиданий, но одновременно лишает тебя возможности проживать собственные достижения."}, "practices": [{"days": "1-7", "name": "Не отменять хорошее", "text": {"m": "Когда происходит что-то приятное, не добавляй к нему оговорки вроде «это случайность» или «ничего особенного». Назови конкретно, что произошло и что тебе в этом понравилось.", "f": "Когда происходит что-то приятное, не добавляй к нему оговорки вроде «это случайность» или «ничего особенного». Назови конкретно, что произошло и что тебе в этом понравилось."}}, {"days": "8-14", "name": "Разрешить себе радость", "text": {"m": "Выбери один свой недавний успех и выдели время, чтобы спокойно его отметить. Не связывай радость с гарантией, что все будет хорошо и дальше.", "f": "Выбери один свой недавний успех и выдели время, чтобы спокойно его отметить. Не связывай радость с гарантией, что все будет хорошо и дальше."}}, {"days": "15-21", "name": "Признать собственный вклад", "text": {"m": "Запиши три результата и конкретные действия, благодаря которым они появились. Отдели собственный вклад от случайных обстоятельств. Не преувеличивай его, но и не уменьшай.", "f": "Запиши три результата и конкретные действия, благодаря которым они появились. Отдели собственный вклад от случайных обстоятельств. Не преувеличивай его, но и не уменьшай."}}]}, {"id": "deval_unworthiness", "title": "Ощущение недостойности хорошего", "questions": [{"id": "q1", "text": {"m": "Когда получаешь что-то хорошее, возникает ли мысль, что ты этого не заслужил или что другие достойнее?", "f": "Когда получаешь что-то хорошее, возникает ли мысль, что ты этого не заслужила или что другие достойнее?"}}, {"id": "q2", "text": {"m": "Тебе бывает неловко принимать подарки, помощь, деньги или признание без ощущения, что теперь ты обязан чем-то отплатить?", "f": "Тебе бывает неловко принимать подарки, помощь, деньги или признание без ощущения, что теперь ты обязана чем-то отплатить?"}}], "explanation": {"m": "Ты можешь воспринимать хорошее как то, что нужно предварительно заслужить. Внутреннее правило: «Мне нельзя просто так получать». Поэтому ты уменьшаешь значение подарков, достижений и возможностей или пытаешься немедленно расплатиться за них. Получать — не всегда означает быть должным.", "f": "Ты можешь воспринимать хорошее как то, что нужно предварительно заслужить. Внутреннее правило: «Мне нельзя просто так получать». Поэтому ты уменьшаешь значение подарков, достижений и возможностей или пытаешься немедленно расплатиться за них. Получать — не всегда означает быть должной."}, "practices": [{"days": "1-7", "name": "Принимать без оправданий", "text": {"m": "Прими небольшую помощь, комплимент или подарок простым «спасибо». Не объясняй, почему это было необязательно, и не обещай немедленно отплатить.", "f": "Прими небольшую помощь, комплимент или подарок простым «спасибо». Не объясняй, почему это было необязательно, и не обещай немедленно отплатить."}}, {"days": "8-14", "name": "Отследить внутренний долг", "text": {"m": "Когда получаешь что-то хорошее, запиши, какое обязательство сразу возникает в голове. Проверь, существует ли оно в реальности или ты создаешь его сам.", "f": "Когда получаешь что-то хорошее, запиши, какое обязательство сразу возникает в голове. Проверь, существует ли оно в реальности или ты создаешь его сама."}}, {"days": "15-21", "name": "Разрешить себе иметь", "text": {"m": "Каждый день замечай одну хорошую вещь, которую ты получил благодаря своим действиям, отношениям или обстоятельствам. Не объясняй, почему она слишком мала или недостаточна. Зафиксируй ее как часть своей жизни.", "f": "Каждый день замечай одну хорошую вещь, которую ты получила благодаря своим действиям, отношениям или обстоятельствам. Не объясняй, почему она слишком мала или недостаточна. Зафиксируй ее как часть своей жизни."}}]}]}, "others": {"name": "Ориентация на чужие желания", "foundations": [{"id": "others_conflict", "title": "Страх конфликта и потери отношений", "questions": [{"id": "q1", "text": {"m": "Ты соглашаешься на то, чего не хочешь, потому что боишься расстроить человека или вызвать конфликт?", "f": "Ты соглашаешься на то, чего не хочешь, потому что боишься расстроить человека или вызвать конфликт?"}}, {"id": "q2", "text": {"m": "Тебе проще отказаться от собственного желания, чем объяснять близким, почему тебе нужно что-то другое?", "f": "Тебе проще отказаться от собственного желания, чем объяснять близким, почему тебе нужно что-то другое?"}}], "explanation": {"m": "Ты ставишь чужие желания выше своих, чтобы сохранить спокойствие и избежать напряжения. Внутреннее правило: «Если я буду настаивать на своем, отношения испортятся». Но постоянное согласие не гарантирует близости, а постепенно отдаляет тебя от собственных потребностей.", "f": "Ты ставишь чужие желания выше своих, чтобы сохранить спокойствие и избежать напряжения. Внутреннее правило: «Если я буду настаивать на своем, отношения испортятся». Но постоянное согласие не гарантирует близости, а постепенно отдаляет тебя от собственных потребностей."}, "practices": [{"days": "1-7", "name": "Не отвечать автоматически", "text": {"m": "На одну необязательную просьбу не отвечай сразу. Скажи, что тебе нужно подумать. Используй паузу, чтобы понять собственное желание, а не только ожидания другого человека.", "f": "На одну необязательную просьбу не отвечай сразу. Скажи, что тебе нужно подумать. Используй паузу, чтобы понять собственное желание, а не только ожидания другого человека."}}, {"days": "8-14", "name": "Озвучить свое предпочтение", "text": {"m": "В бытовой или совместной ситуации первым назови собственное предпочтение. Не требуй согласия, но и не отказывайся от своего варианта только из-за возможного несогласия.", "f": "В бытовой или совместной ситуации первой назови собственное предпочтение. Не требуй согласия, но и не отказывайся от своего варианта только из-за возможного несогласия."}}, {"days": "15-21", "name": "Спокойный отказ", "text": {"m": "Откажись от одного необязательного дела, на которое не хватает желания или ресурса. Используй короткую формулировку без длинных оправданий. Заметь, что происходит после отказа.", "f": "Откажись от одного необязательного дела, на которое не хватает желания или ресурса. Используй короткую формулировку без длинных оправданий. Заметь, что происходит после отказа."}}]}, {"id": "others_identity", "title": "Роль хорошего человека", "questions": [{"id": "q1", "text": {"m": "Ты чувствуешь вину, когда выбираешь собственный интерес вместо того, чтобы быть удобным или полезным?", "f": "Ты чувствуешь вину, когда выбираешь собственный интерес вместо того, чтобы быть удобной или полезной?"}}, {"id": "q2", "text": {"m": "Тебе важно, чтобы окружающие считали тебя добрым и отзывчивым, даже если ради этого приходится отказываться от себя?", "f": "Тебе важно, чтобы окружающие считали тебя доброй и отзывчивой, даже если ради этого приходится отказываться от себя?"}}], "explanation": {"m": "Ты связываешь право на собственные желания с образом хорошего человека. Внутреннее правило: «Хороший человек сначала думает о других». Поэтому забота о себе может ощущаться как эгоизм. Но собственные интересы не отменяют твою способность любить и заботиться.", "f": "Ты связываешь право на собственные желания с образом хорошего человека. Внутреннее правило: «Хороший человек сначала думает о других». Поэтому забота о себе может ощущаться как эгоизм. Но собственные интересы не отменяют твою способность любить и заботиться."}, "practices": [{"days": "1-7", "name": "Вернуть себе маленький выбор", "text": {"m": "Каждый день самостоятельно выбери одну небольшую вещь: еду, маршрут, занятие или время отдыха. Не спрашивай разрешения на то, что не требует согласования.", "f": "Каждый день самостоятельно выбери одну небольшую вещь: еду, маршрут, занятие или время отдыха. Не спрашивай разрешения на то, что не требует согласования."}}, {"days": "8-14", "name": "Разрешить себе хотеть", "text": {"m": "Запиши пять желаний, которые не связаны с пользой для окружающих. Выбери одно и сделай небольшой шаг к нему. Не требуй от себя объяснения, почему ты этого хочешь.", "f": "Запиши пять желаний, которые не связаны с пользой для окружающих. Выбери одно и сделай небольшой шаг к нему. Не требуй от себя объяснения, почему ты этого хочешь."}}, {"days": "15-21", "name": "Забота без самопожертвования", "text": {"m": "Перед тем как помочь кому-то, оцени свои силы и желание. Выбери один случай, в котором ты поможешь в комфортном для себя объеме, а не возьмешь на себя все.", "f": "Перед тем как помочь кому-то, оцени свои силы и желание. Выбери один случай, в котором ты поможешь в комфортном для себя объеме, а не возьмешь на себя все."}}]}]}, "avoid": {"name": "Избегание действий", "foundations": [{"id": "avoid_failure", "title": "Страх неудачи и ее последствий", "questions": [{"id": "q1", "text": {"m": "Ты откладываешь важный шаг, потому что заранее представляешь, сколько проблем может возникнуть, если не получится?", "f": "Ты откладываешь важный шаг, потому что заранее представляешь, сколько проблем может возникнуть, если не получится?"}}, {"id": "q2", "text": {"m": "Ты часто выбираешь привычное бездействие, потому что оно кажется безопаснее неопределенного результата?", "f": "Ты часто выбираешь привычное бездействие, потому что оно кажется безопаснее неопределенного результата?"}}], "explanation": {"m": "Бездействие помогает тебе временно не сталкиваться с риском. Внутреннее правило: «Если не начну, не придется переживать неудачу». Но отсутствие действия тоже имеет последствия: время проходит, возможности остаются неиспользованными, а напряжение накапливается.", "f": "Бездействие помогает тебе временно не сталкиваться с риском. Внутреннее правило: «Если не начну, не придется переживать неудачу». Но отсутствие действия тоже имеет последствия: время проходит, возможности остаются неиспользованными, а напряжение накапливается."}, "practices": [{"days": "1-7", "name": "Первый шаг за пять минут", "text": {"m": "Выбери одно отложенное дело и потрать на него пять минут. Не ставь задачу закончить все. Твоя цель — начать и зафиксировать, что произошло после начала.", "f": "Выбери одно отложенное дело и потрать на него пять минут. Не ставь задачу закончить все. Твоя цель — начать и зафиксировать, что произошло после начала."}}, {"days": "8-14", "name": "Проверить реальный риск", "text": {"m": "Перед действием запиши худший сценарий, наиболее вероятный сценарий и один способ снизить риск. Отдели реальную опасность от тревожного предположения. Затем сделай безопасную часть шага.", "f": "Перед действием запиши худший сценарий, наиболее вероятный сценарий и один способ снизить риск. Отдели реальную опасность от тревожного предположения. Затем сделай безопасную часть шага."}}, {"days": "15-21", "name": "Завершать маленькие циклы", "text": {"m": "Каждый день выбери одно небольшое дело, которое можно довести до завершения за короткое время. Закончи его и отметь результат. Постепенно возвращай себе опыт действия и завершения.", "f": "Каждый день выбери одно небольшое дело, которое можно довести до завершения за короткое время. Закончи его и отметь результат. Постепенно возвращай себе опыт действия и завершения."}}]}, {"id": "avoid_overwhelm", "title": "Перегрузка и страх объема", "questions": [{"id": "q1", "text": {"m": "Когда видишь большой объем работы, ты теряешь ясность и не знаешь, с какой части начать?", "f": "Когда видишь большой объем работы, ты теряешь ясность и не знаешь, с какой части начать?"}}, {"id": "q2", "text": {"m": "Ты откладываешь даже важные для себя дела, потому что кажется, что для них нужно слишком много сил и времени?", "f": "Ты откладываешь даже важные для себя дела, потому что кажется, что для них нужно слишком много сил и времени?"}}], "explanation": {"m": "Ты воспринимаешь задачу целиком, вместе со всеми ее этапами и возможными трудностями. Внутреннее правило: «Если я не могу справиться со всем, лучше пока не начинать». Это не обязательно отсутствие желания: иногда масштаб задачи превышает доступный сейчас ресурс.", "f": "Ты воспринимаешь задачу целиком, вместе со всеми ее этапами и возможными трудностями. Внутреннее правило: «Если я не могу справиться со всем, лучше пока не начинать». Это не обязательно отсутствие желания: иногда масштаб задачи превышает доступный сейчас ресурс."}, "practices": [{"days": "1-7", "name": "Разделить большое на малое", "text": {"m": "Возьми одну большую задачу и раздели ее на пять конкретных действий. Выбери самое маленькое, которое можно выполнить за 10 минут. Не планируй сразу весь путь.", "f": "Возьми одну большую задачу и раздели ее на пять конкретных действий. Выбери самое маленькое, которое можно выполнить за 10 минут. Не планируй сразу весь путь."}}, {"days": "8-14", "name": "Работать в пределах ресурса", "text": {"m": "Перед началом дела оцени доступные силы по шкале от 1 до 10. Выбери объем работы, соответствующий сегодняшнему ресурсу. Не пытайся компенсировать усталость требованием сделать все.", "f": "Перед началом дела оцени доступные силы по шкале от 1 до 10. Выбери объем работы, соответствующий сегодняшнему ресурсу. Не пытайся компенсировать усталость требованием сделать все."}}, {"days": "15-21", "name": "Один завершенный фрагмент", "text": {"m": "Каждый день выбирай один конкретный фрагмент большой задачи и доводи его до завершения. В дневнике отмечай не оставшийся объем, а то, что уже сделано.", "f": "Каждый день выбирай один конкретный фрагмент большой задачи и доводи его до завершения. В дневнике отмечай не оставшийся объем, а то, что уже сделано."}}]}]}};
GTXT.menu={"information": {"id": "menu_information", "title": {"m": "Как устроен твой путь", "f": "Как устроен твой путь"}, "subtitle": {"m": "Несколько слов перед продолжением исследования", "f": "Несколько слов перед продолжением исследования"}, "paragraphs": [{"m": "«Путь Алхимика» — пространство самостоятельного исследования себя. Здесь ты будешь встречаться с разными сторонами своей личности, замечать привычные реакции, исследовать внутренние противоречия и искать новые способы взаимодействия с собственной жизнью.", "f": "«Путь Алхимика» — пространство самостоятельного исследования себя. Здесь ты будешь встречаться с разными сторонами своей личности, замечать привычные реакции, исследовать внутренние противоречия и искать новые способы взаимодействия с собственной жизнью."}, {"m": "Тебя ждут несколько глав путешествия. Каждая открывает отдельную область исследования: исходную конфигурацию, привычные установки, внутренние противоречия, ценности, желания и новые направления движения.", "f": "Тебя ждут несколько глав путешествия. Каждая открывает отдельную область исследования: исходную конфигурацию, привычные установки, внутренние противоречия, ценности, желания и новые направления движения."}, {"m": "Отвечай так, как действительно думаешь и чувствуешь сейчас. Здесь нет правильных ответов, оценок и соревнования. Не пытайся выглядеть лучше или соответствовать ожидаемому образу. Точность исследования начинается с честности перед собой.", "f": "Отвечай так, как действительно думаешь и чувствуешь сейчас. Здесь нет правильных ответов, оценок и соревнования. Не пытайся выглядеть лучше или соответствовать ожидаемому образу. Точность исследования начинается с честности перед собой."}, {"m": "Ты можешь остановиться, вернуться к предыдущему этапу, перечитать материалы или сделать паузу. Не обязательно проходить весь путь за один раз. Важнее не скорость, а качество внимания к себе.", "f": "Ты можешь остановиться, вернуться к предыдущему этапу, перечитать материалы или сделать паузу. Не обязательно проходить весь путь за один раз. Важнее не скорость, а качество внимания к себе."}, {"m": "Твои ответы и записи хранятся в профиле на твоем устройстве. Ты можешь сохранить резервную копию и восстановить ее позднее. Не передавай файл профиля другим людям, если не хочешь раскрывать свои личные записи.", "f": "Твои ответы и записи хранятся в профиле на твоем устройстве. Ты можешь сохранить резервную копию и восстановить ее позднее. Не передавай файл профиля другим людям, если не хочешь раскрывать свои личные записи."}, {"m": "Материалы игры предлагают способы осмысления собственного опыта, а не медицинский или психологический диагноз. Ты самостоятельно определяешь, какие выводы тебе подходят и какие изменения готов внедрять.", "f": "Материалы игры предлагают способы осмысления собственного опыта, а не медицинский или психологический диагноз. Ты самостоятельно определяешь, какие выводы тебе подходят и какие изменения готова внедрять."}], "button": {"m": "Вернуться к путешествию", "f": "Вернуться к путешествию"}}, "themes": {"id": "menu_themes", "title": {"m": "Твои внутренние узоры", "f": "Твои внутренние узоры"}, "subtitle": {"m": "Как читать карту тематических проявлений", "f": "Как читать карту тематических проявлений"}, "paragraphs": [{"m": "Внутренний узор — это повторяющаяся закономерность в том, как ты воспринимаешь события, реагируешь на них, принимаешь решения и взаимодействуешь с окружающим миром.", "f": "Внутренний узор — это повторяющаяся закономерность в том, как ты воспринимаешь события, реагируешь на них, принимаешь решения и взаимодействуешь с окружающим миром."}, {"m": "Одна и та же внешняя ситуация может запускать у разных людей совершенно разные внутренние процессы. Поэтому важно не только то, что происходит с тобой, но и то, какое значение ты придаешь происходящему, чего ожидаешь и от чего пытаешься себя защитить.", "f": "Одна и та же внешняя ситуация может запускать у разных людей совершенно разные внутренние процессы. Поэтому важно не только то, что происходит с тобой, но и то, какое значение ты придаешь происходящему, чего ожидаешь и от чего пытаешься себя защитить."}, {"m": "Тематические узоры помогают увидеть повторяющиеся мотивы: отношение к себе, ответственности, признанию, безопасности, выбору, действиям и другим областям жизни. Они рассматриваются через сочетание расчетных показателей и твоих собственных ответов.", "f": "Тематические узоры помогают увидеть повторяющиеся мотивы: отношение к себе, ответственности, признанию, безопасности, выбору, действиям и другим областям жизни. Они рассматриваются через сочетание расчетных показателей и твоих собственных ответов."}, {"m": "Ведущий узор — не ярлык и не окончательное описание тебя. Это наиболее заметная закономерность в исследуемой конфигурации. За ней могут находиться разные внутренние основания. Именно поэтому тебе будут предложены дополнительные вопросы, позволяющие уточнить, что поддерживает конкретную реакцию.", "f": "Ведущий узор — не ярлык и не окончательное описание тебя. Это наиболее заметная закономерность в исследуемой конфигурации. За ней могут находиться разные внутренние основания. Именно поэтому тебе будут предложены дополнительные вопросы, позволяющие уточнить, что поддерживает конкретную реакцию."}, {"m": "У каждого узора есть две стороны. Первая — защитная: когда-то определенная реакция могла помогать тебе сохранять безопасность, отношения или ощущение контроля. Вторая — ограничивающая: если продолжать действовать автоматически, прежний способ защиты может мешать новым решениям.", "f": "У каждого узора есть две стороны. Первая — защитная: когда-то определенная реакция могла помогать тебе сохранять безопасность, отношения или ощущение контроля. Вторая — ограничивающая: если продолжать действовать автоматически, прежний способ защиты может мешать новым решениям."}, {"m": "Твоя задача — не уничтожить старый узор, а понять его функцию, увидеть доступные альтернативы и научиться выбирать реакцию осознанно. Результаты можно пересматривать по мере накопления нового опыта.", "f": "Твоя задача — не уничтожить старый узор, а понять его функцию, увидеть доступные альтернативы и научиться выбирать реакцию осознанно. Результаты можно пересматривать по мере накопления нового опыта."}], "button": {"m": "Понятно, продолжить", "f": "Понятно, продолжить"}}};
GTXT.guard={"id": "final_ego_guard", "title": {"m": "Встреча со Стражем", "f": "Встреча со Стражем"}, "intro": {"m": "Перед тобой стоит Страж. Его лицо кажется знакомым. Он говорит голосом твоей ведущей установки. Все это время он охранял границу между привычным миром и неизвестностью.", "f": "Перед тобой стоит Страж. Его лицо кажется знакомым. Он говорит голосом твоей ведущей установки. Все это время он охранял границу между привычным миром и неизвестностью."}, "dynamic_context": {"pattern": "{{pattern_name}}", "rule": "{{leading_rule}}", "benefit": "{{secondary_benefit}}", "instruction": "Подставлять значения из рассчитанного профиля игрока. Если конкретное основание не определено, использовать общую формулировку ведущей установки."}, "dialogue": [{"id": "guard_01", "purpose": "recognition", "guardian": {"m": "Ты снова хочешь все изменить? Но вспомни, сколько раз я удерживал тебя от опасности. Я заставлял тебя действовать привычным способом, потому что неизвестность казалась слишком рискованной. Разве ты не видишь, что без меня можешь потерять то, что имеешь?", "f": "Ты снова хочешь все изменить? Но вспомни, сколько раз я удерживал тебя от опасности. Я заставлял тебя действовать привычным способом, потому что неизвестность казалась слишком рискованной. Разве ты не видишь, что без меня можешь потерять то, что имеешь?"}, "question": {"m": "Что ты теперь понимаешь о моей роли?", "f": "Что ты теперь понимаешь о моей роли?"}, "options": [{"id": "g1_a", "label": "ego", "text": {"m": "Ты прав. Лучше оставить все как есть. Привычный способ безопаснее, даже если мне приходится отказываться от желаемого.", "f": "Ты прав. Лучше оставить все как есть. Привычный способ безопаснее, даже если мне приходится отказываться от желаемого."}, "outcome": {"m": "Ты пока продолжаешь считать привычную защиту единственно возможным способом справляться с ситуацией.", "f": "Ты пока продолжаешь считать привычную защиту единственно возможным способом справляться с ситуацией."}}, {"id": "g1_b", "label": "self", "text": {"m": "Я вижу, что ты пытался меня защитить. Но привычная безопасность не всегда означает, что этот способ нужен мне сейчас.", "f": "Я вижу, что ты пытался меня защитить. Но привычная безопасность не всегда означает, что этот способ нужен мне сейчас."}, "outcome": {"m": "Ты отделяешь намерение защиты от необходимости продолжать прежнее поведение.", "f": "Ты отделяешь намерение защиты от необходимости продолжать прежнее поведение."}}, {"id": "g1_c", "label": "ego", "text": {"m": "Ты мне мешал. Если бы не ты, моя жизнь давно была бы другой. Я хочу избавиться от тебя.", "f": "Ты мне мешал. Если бы не ты, моя жизнь давно была бы другой. Я хочу избавиться от тебя."}, "outcome": {"m": "Ты замечаешь ограничение, но пока воспринимаешь собственную защиту как врага, которого необходимо победить.", "f": "Ты замечаешь ограничение, но пока воспринимаешь собственную защиту как врага, которого необходимо победить."}}]}, {"id": "guard_02", "purpose": "secondary_benefit", "guardian": {"m": "Ты называешь меня ограничением, но не замечаешь, что получал благодаря мне. Я избавлял тебя от риска, позволял избегать неприятных разговоров, чужой оценки и неопределенности. Я давал тебе причину не делать то, чего ты боялся.", "f": "Ты называешь меня ограничением, но не замечаешь, что получала благодаря мне. Я избавлял тебя от риска, позволял избегать неприятных разговоров, чужой оценки и неопределенности. Я давал тебе причину не делать то, чего ты боялась."}, "question": {"m": "Что на самом деле удерживало тебя рядом со мной?", "f": "Что на самом деле удерживало тебя рядом со мной?"}, "options": [{"id": "g2_a", "label": "ego", "text": {"m": "Ничего. Я просто не понимал, что происходит. Теперь я хочу забыть обо всем этом.", "f": "Ничего. Я просто не понимала, что происходит. Теперь я хочу забыть обо всем этом."}, "outcome": {"m": "Ты пока не исследуешь выгоду старой конструкции и пытаешься просто от нее отказаться.", "f": "Ты пока не исследуешь выгоду старой конструкции и пытаешься просто от нее отказаться."}}, {"id": "g2_b", "label": "ego", "text": {"m": "Ты давал мне возможность не рисковать. И я готов продолжать платить эту цену, если так спокойнее.", "f": "Ты давал мне возможность не рисковать. И я готова продолжать платить эту цену, если так спокойнее."}, "outcome": {"m": "Ты признаешь защитную функцию, но пока предпочитаешь сохранять прежнюю цену за привычное спокойствие.", "f": "Ты признаешь защитную функцию, но пока предпочитаешь сохранять прежнюю цену за привычное спокойствие."}}, {"id": "g2_c", "label": "self", "text": {"m": "Ты давал мне определенное спокойствие. Теперь я вижу, что вместе с ним получал ограничения. Я могу сохранить безопасность, не отказываясь от собственного выбора.", "f": "Ты давал мне определенное спокойствие. Теперь я вижу, что вместе с ним получала ограничения. Я могу сохранить безопасность, не отказываясь от собственного выбора."}, "outcome": {"m": "Ты распознаешь вторичную выгоду и начинаешь отделять ее от цены, которую платишь за прежний способ защиты.", "f": "Ты распознаешь вторичную выгоду и начинаешь отделять ее от цены, которую платишь за прежний способ защиты."}}]}, {"id": "guard_03", "purpose": "identity_separation", "guardian": {"m": "Но если ты перестанешь действовать так, как я велел, кем ты станешь? Если больше не будешь всем помогать, все контролировать, добиваться одобрения, избегать ошибок или ждать подходящего момента — на что ты будешь опираться? Возможно, без меня ты вообще не знаешь, кто ты.", "f": "Но если ты перестанешь действовать так, как я велел, кем ты станешь? Если больше не будешь всем помогать, все контролировать, добиваться одобрения, избегать ошибок или ждать подходящего момента — на что ты будешь опираться? Возможно, без меня ты вообще не знаешь, кто ты."}, "question": {"m": "Кто ты, если твоя привычная реакция больше не определяет твои решения?", "f": "Кто ты, если твоя привычная реакция больше не определяет твои решения?"}, "options": [{"id": "g3_a", "label": "ego", "text": {"m": "Наверное, мне придется стать совершенно другим человеком и отказаться от всего, что было раньше.", "f": "Наверное, мне придется стать совершенно другим человеком и отказаться от всего, что было раньше."}, "outcome": {"m": "Ты пока воспринимаешь изменение поведения как необходимость отказаться от собственной истории и прежнего опыта.", "f": "Ты пока воспринимаешь изменение поведения как необходимость отказаться от собственной истории и прежнего опыта."}}, {"id": "g3_b", "label": "self", "text": {"m": "Я остаюсь собой. Мои качества, опыт и ценность не исчезают, если я перестаю действовать автоматически.", "f": "Я остаюсь собой. Мои качества, опыт и ценность не исчезают, если я перестаю действовать автоматически."}, "outcome": {"m": "Ты отделяешь собственную идентичность от привычного защитного поведения.", "f": "Ты отделяешь собственную идентичность от привычного защитного поведения."}}, {"id": "g3_c", "label": "ego", "text": {"m": "Я не могу ничего изменить. Я такой человек, и мне придется жить с этим.", "f": "Я не могу ничего изменить. Я такой человек, и мне придется жить с этим."}, "outcome": {"m": "Ты пока отождествляешь привычную реакцию с неизменной частью своей личности.", "f": "Ты пока отождествляешь привычную реакцию с неизменной частью своей личности."}}]}, {"id": "guard_04", "purpose": "new_choice", "guardian": {"m": "Хорошо. Допустим, ты меня услышал. Но завтра снова возникнет знакомая ситуация. Кто будет решать, как тебе поступить? Я могу снова взять управление на себя. Я знаю старый путь. А ты пока только учишься выбирать.", "f": "Хорошо. Допустим, ты меня услышала. Но завтра снова возникнет знакомая ситуация. Кто будет решать, как тебе поступить? Я могу снова взять управление на себя. Я знаю старый путь. А ты пока только учишься выбирать."}, "question": {"m": "Какое место ты теперь отводишь мне в своей жизни?", "f": "Какое место ты теперь отводишь мне в своей жизни?"}, "options": [{"id": "g4_a", "label": "ego", "text": {"m": "Оставь все как прежде. Я пока не готов рисковать и брать на себя ответственность за новый выбор.", "f": "Оставь все как прежде. Я пока не готова рисковать и брать на себя ответственность за новый выбор."}, "outcome": {"m": "Ты пока выбираешь привычную стратегию и сохраняешь прежний порядок управления.", "f": "Ты пока выбираешь привычную стратегию и сохраняешь прежний порядок управления."}}, {"id": "g4_b", "label": "self", "text": {"m": "Ты можешь напоминать мне об опасности, но решение теперь принимаю я. Я буду учитывать твой опыт, проверять реальность и выбирать действие сам.", "f": "Ты можешь напоминать мне об опасности, но решение теперь принимаю я. Я буду учитывать твой опыт, проверять реальность и выбирать действие сама."}, "outcome": {"m": "Ты возвращаешь себе право выбора и оставляешь защитной функции ее полезное назначение.", "f": "Ты возвращаешь себе право выбора и оставляешь защитной функции ее полезное назначение."}}, {"id": "g4_c", "label": "ego", "text": {"m": "Я хочу, чтобы ты исчез навсегда. Мне не нужна никакая твоя помощь.", "f": "Я хочу, чтобы ты исчез навсегда. Мне не нужна никакая твоя помощь."}, "outcome": {"m": "Ты пытаешься полностью исключить защиту вместо того, чтобы научиться управлять ее включением.", "f": "Ты пытаешься полностью исключить защиту вместо того, чтобы научиться управлять ее включением."}}]}], "final": {"title": {"m": "Страж меняет свое место", "f": "Страж меняет свое место"}, "guardian": {"m": "Страж опускает оружие. Его броня начинает светиться изнутри. Он больше не преграждает тебе дорогу. Ты замечаешь, что за тяжелыми доспехами все это время находился не враг, а часть твоего собственного опыта.", "f": "Страж опускает оружие. Его броня начинает светиться изнутри. Он больше не преграждает тебе дорогу. Ты замечаешь, что за тяжелыми доспехами все это время находился не враг, а часть твоего собственного опыта."}, "guardian_dialogue": {"m": "Я не исчезну. Я помню то, от чего когда-то защищал тебя. Но теперь мне не нужно управлять каждым твоим шагом. Я буду стоять рядом и предупреждать, когда это действительно необходимо. Решение останется за тобой.", "f": "Я не исчезну. Я помню то, от чего когда-то защищал тебя. Но теперь мне не нужно управлять каждым твоим шагом. Я буду стоять рядом и предупреждать, когда это действительно необходимо. Решение останется за тобой."}, "player_response": {"m": "Я принимаю твой опыт, но больше не передаю тебе право выбирать за меня. Ты можешь быть моей опорой, но не моим хозяином.", "f": "Я принимаю твой опыт, но больше не передаю тебе право выбирать за меня. Ты можешь быть моей опорой, но не моим хозяином."}, "transformation": {"old_role": "Автоматический защитник и управляющий поведением", "new_role": "Советник и система предупреждения", "artifact": {"id": "guardian_companion", "name": {"m": "Хранитель опыта", "f": "Хранительница опыта"}, "description": {"m": "Твой бывший Страж становится Хранителем опыта. Он напоминает о прежних способах защиты, но больше не принимает решения вместо тебя.", "f": "Твоя бывшая Страж становится Хранительницей опыта. Она напоминает о прежних способах защиты, но больше не принимает решения вместо тебя."}}}, "closing": {"m": "Ты не обязан уничтожать части своей личности, чтобы меняться. Ты можешь понять, зачем они появились, забрать из них полезный опыт и выбрать, как действовать дальше. Страж остается рядом. Но теперь путь выбираешь ты.", "f": "Ты не обязана уничтожать части своей личности, чтобы меняться. Ты можешь понять, зачем они появились, забрать из них полезный опыт и выбрать, как действовать дальше. Страж остается рядом. Но теперь путь выбираешь ты."}, "button": {"m": "Принять артефакт", "f": "Принять артефакт"}}};
